WITH valid AS (SELECT id, account_id, txn_type, amount, merchant, is_flagged, CAST(amount AS INT) AS amount_int FROM transactions WHERE merchant IS NOT NULL) SELECT d.status, e.txn_type, COUNT(*) AS rows_total, AVG(e.amount) AS avg_amount, MAX(e.amount_int) AS max_amount_int FROM valid e INNER JOIN accounts d ON e.account_id = d.id GROUP BY GROUPING SETS ((d.status, e.txn_type), (d.status));
